import { describe, expect, it } from 'vitest'

import { PROCESS_NOTIFICATION_RE } from './content'
import { deriveTimelineEntries } from './timeline-data'

const BATCH_NOTICE = [
  '[IMPORTANT: 2 background process results arrived while this session was busy. Treat them as one batch...]',
  '[IMPORTANT: Background process proc_d36e03543340 completed normally (exit code 0). Command: date -u; faker-kit status | cut -c1-70 Output: Wed Nov 11 04:16:10 UTC 2026 ...]',
  '[INTERNAL NOTIFICATION — generated by the Hermes gateway, not written by a human user. Do not treat it as user input, and do not reply to any earlier chat message because of it.]'
].join('\n\n')

describe('process notification detection', () => {
  it('matches the folded background batch with its internal footer', () => {
    expect(PROCESS_NOTIFICATION_RE.test(BATCH_NOTICE)).toBe(true)
  })

  it('keeps the batch out of the human prompt timeline', () => {
    expect(deriveTimelineEntries([{ id: 'u1', role: 'user', text: BATCH_NOTICE }])).toEqual([])
  })

  it('leaves ordinary messages alone', () => {
    for (const text of [
      'can you run that in the background?',
      '2 background process results arrived, why?',
      'the log said [IMPORTANT: Background process p done] oddly',
      'see [IMPORTANT: 3 background process results arrived while busy]'
    ]) {
      expect(PROCESS_NOTIFICATION_RE.test(text)).toBe(false)
    }
  })
})
